import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { delimiter, dirname, join } from 'node:path';
import { after, before, describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';

const installer = join(
  dirname(fileURLToPath(import.meta.url)),
  '..',
  '..',
  'install',
  'install.sh',
);

// Generated by install.sh itself, with docker and curl stubbed first on PATH: no daemon, no network.
const DOCKER_STUB = `#!/bin/sh
echo "$*" >> "$STUB_DOCKER_LOG"
has() { case " $1 " in *" $2 "*) return 0 ;; esac; return 1; }
case "$1" in
  compose)
    case " $* " in
      *" --short "*) echo 2.30.0 ;;
      *" version "*) echo "Docker Compose version v2.30.0" ;;
    esac ;;
  volume)
    case "$2" in
      ls)
        for a in "$@"; do case "$a" in name=^*) prefix=\${a#name=^} ;; esac; done
        for v in $STUB_VOLUMES; do case "$v" in "$prefix"*) echo "$v" ;; esac; done ;;
      inspect | rm)
        has "$STUB_VOLUMES" "$3" || { echo "no such volume: $3" >&2; exit 1; }
        if [ "$2" = rm ] && has "$STUB_VOLUMES_HELD" "$3"; then echo "volume $3 is in use" >&2; exit 1; fi ;;
    esac ;;
  ps)
    for a in "$@"; do
      case "$a" in volume=*) if has "$STUB_VOLUMES_HELD" "\${a#volume=}"; then for h in $STUB_HOLDERS; do echo "$h"; done; fi ;; esac
    done ;;
  network)
    case "$2" in
      ls) for n in $STUB_NETWORKS; do echo "$n"; done ;;
      inspect) case "$*" in *Containers*) echo "$STUB_HOLDERS" ;; *) echo "$3" ;; esac ;;
      rm) if has "$STUB_NETWORKS_HELD" "$3"; then echo "network $3 has active endpoints" >&2; exit 1; fi ;;
    esac ;;
esac
exit 0
`;

const CURL_STUB = `#!/bin/sh
out=; prev=
for a in "$@"; do
  if [ "$prev" = -o ]; then out=$a; fi
  prev=$a
done
case "$out" in docker-compose*) echo 'services: {}' > "$out" ;; esac
exit 0
`;

const ID = 'unit';
const HOLDERS = ['ext-pg', 'ext-shell'];
const RUNTIME = ['postgres_data', 'redis_data', 'mailpit_data', 'ollama_data'].map(
  (name) => `${ID}_${name}`,
);
const WORK = [
  'repos',
  'bundles',
  'wrappers',
  'squid_configs',
  'ddev_ca',
  'npm_cache',
  'ddev_registry_cache',
].map((name) => `${ID}_${name}`);
const PER_TASK = [`${ID}_cli_auth_t1`, `${ID}_ide_t1`];
const ALL = [...RUNTIME, ...WORK, ...PER_TASK];

const NETWORK = `${ID}-network`;
const NETWORK_HELD = {
  STUB_NETWORKS: NETWORK,
  STUB_NETWORKS_HELD: NETWORK,
  STUB_HOLDERS: 'ext-pg',
};

describe('the uninstall.sh that install.sh writes', () => {
  let root;
  let uninstall;
  let env;
  let runs = 0;

  before(() => {
    root = mkdtempSync(join(tmpdir(), 'haive-uninstall-sh-'));
    const bin = join(root, 'bin');
    mkdirSync(bin);
    writeFileSync(join(bin, 'docker'), DOCKER_STUB, { mode: 0o755 });
    writeFileSync(join(bin, 'curl'), CURL_STUB, { mode: 0o755 });
    env = {
      ...process.env,
      PATH: `${bin}${delimiter}${process.env.PATH}`,
      DOCKER_HOST: 'unix:///nonexistent', // a docker that slips past the stub finds no daemon
      HOME: root,
      HAIVE_GPU: 'cpu',
      STUB_DOCKER_LOG: join(root, 'install.log'),
    };
    const dir = join(root, 'install');
    const gen = spawnSync(
      'sh',
      [installer, '--version', '9.9.9', '--install-id', ID, '--dir', dir, '--no-start'],
      { encoding: 'utf8', env },
    );
    assert.equal(gen.status, 0, gen.stdout + gen.stderr);
    uninstall = join(dir, 'uninstall.sh');
  });

  after(() => rmSync(root, { recursive: true, force: true }));

  const run = (args, stub = {}) => {
    const log = join(root, `run-${++runs}.log`);
    const out = spawnSync('sh', [uninstall, ...args], {
      encoding: 'utf8',
      env: { ...env, STUB_DOCKER_LOG: log, STUB_VOLUMES: ALL.join(' '), ...stub },
    });
    const calls = existsSync(log) ? readFileSync(log, 'utf8').trim().split('\n') : [];
    return { out, calls, lines: out.stdout.split('\n') };
  };

  const heldBy = (volumes) => ({
    STUB_VOLUMES_HELD: volumes.join(' '),
    STUB_HOLDERS: HOLDERS.join(' '),
  });

  const said = (lines, text) => lines.some((l) => l.includes(text));

  const assertNamedWithHolders = ({ out, calls, lines }, volumes) => {
    for (const v of volumes) {
      const named = lines.some((l) => l.includes(v) && HOLDERS.every((h) => l.includes(h)));
      assert.ok(named, `${v} is not named with its holders:\n${out.stdout}`);
      assert.ok(!said(lines, `removed ${v}`), out.stdout);
      const asked = calls.some((c) => c.startsWith('ps') && c.includes(`volume=${v}`));
      assert.ok(asked, calls.join('\n'));
    }
  };

  // Like a left-behind network, a left-behind volume shows in the summary, not in the exit status (0).
  it('--purge: volumes it cannot remove are named with their holders, and the closing line says what is left', () => {
    const held = [`${ID}_postgres_data`, `${ID}_repos`, `${ID}_cli_auth_t1`];
    const result = run(['--purge', '--yes'], heldBy(held));
    const { out, lines } = result;
    assert.equal(out.status, 0, out.stdout + out.stderr);
    assertNamedWithHolders(result, held);
    assert.ok(said(lines, `removed ${ID}_redis_data`), out.stdout);
    assert.doesNotMatch(out.stdout, /Everything this install owned is gone\./);
    assert.match(out.stdout, new RegExp(`^ *docker volume rm ${held.join(' ')}$`, 'm'));
  });

  it('without --purge: a runtime volume it cannot remove is named too, and the work volumes are left alone', () => {
    const held = [`${ID}_postgres_data`];
    const result = run(['--yes'], heldBy(held));
    const { out, calls } = result;
    assert.equal(out.status, 0, out.stdout + out.stderr);
    assertNamedWithHolders(result, held);
    assert.doesNotMatch(out.stdout, /The stack is gone either way/);
    assert.match(out.stdout, new RegExp(`^ *docker volume rm ${held.join(' ')}$`, 'm'));
    assert.deepEqual(
      calls.filter((c) => c.startsWith('volume rm')),
      RUNTIME.map((v) => `volume rm ${v}`),
    );
  });

  it('a volume that does not exist is not an error', () => {
    const present = [`${ID}_postgres_data`, `${ID}_repos`];
    const { out, lines } = run(['--purge', '--yes'], { STUB_VOLUMES: present.join(' ') });
    assert.equal(out.status, 0, out.stdout + out.stderr);
    for (const v of present) assert.ok(said(lines, `removed ${v}`), out.stdout);
    for (const v of ALL.filter((name) => !present.includes(name))) {
      assert.ok(!out.stdout.includes(v), `${v} does not exist but is mentioned:\n${out.stdout}`);
    }
    assert.match(out.stdout, /Everything this install owned is gone\./);
  });

  it('a network it cannot remove still changes the closing line', () => {
    const { out } = run(['--purge', '--yes'], NETWORK_HELD);
    assert.equal(out.status, 0, out.stdout + out.stderr);
    assert.doesNotMatch(out.stdout, /Everything this install owned is gone\./);
    assert.match(out.stdout, new RegExp(`docker network ls -q --filter name=\\^${ID}- `));
    assert.doesNotMatch(out.stdout, /docker volume rm/);
  });

  it('a network and a volume left together are both in the closing line', () => {
    const held = [`${ID}_postgres_data`];
    const { out } = run(['--purge', '--yes'], { ...NETWORK_HELD, ...heldBy(held) });
    assert.equal(out.status, 0, out.stdout + out.stderr);
    assert.doesNotMatch(out.stdout, /Everything this install owned is gone\./);
    assert.match(out.stdout, new RegExp(`docker network ls -q --filter name=\\^${ID}- `));
    assert.match(out.stdout, new RegExp(`^ *docker volume rm ${held.join(' ')}$`, 'm'));
  });
});
